get_product_page.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\ProductPage;

$response = ProductPage::getProductPage($client);

$settings = $response->map['product_page'];
echo 'Description shown: ', $settings['configuration']['details']['display_description'] ? 'true' : 'false', PHP_EOL;
echo 'Quick view: ', $settings['quick_view']['product_quick_view'] ? 'true' : 'false', PHP_EOL;

patch_product_page.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\ProductPage;

$response = ProductPage::patchProductPage($client, [
    'product_page' => [
        'configuration' => ['details' => ['display_description' => true]],
        'up_sell' => ['short_description' => true],
    ],
]);

$settings = $response->map['product_page'];
echo $settings['configuration']['details']['display_description'] ? 'true' : 'false', PHP_EOL;
echo $settings['up_sell']['short_description'] ? 'true' : 'false', PHP_EOL;
